obs = [
    ("⊕", 19, 5, 25),
    ("⊗", 19, 5, 94),
    ("◇", 19, 5, 19),
    ("▽", 26, 3, 23),
    ("⊘", 26, 3, 49),
    ("⊛", 26, 3, 35),
    ("⊞", 26, 3, 29),
    ("⊠", 26, 3, 31),
    ("△", 26, 3, 23),
]

atoms = ["a", "b", "n", "i", "d", "1", "2", "3"]
lvl1 = list(atoms)
for x in atoms:
    for y in atoms:
        if x in "123" and y in "123": continue
        for op in ["+", "-", "*", "//", "%", "**"]:
            if op == "**" and y not in ("2", "3", "n", "i", "d"): continue
            lvl1.append(f"({x}{op}{y})")

# check a + y, etc for ⊛ (26, 3) -> 35 and ⊘ (26, 3) -> 49 and ⊗ (19, 5) -> 94
for sym, a_val, b_val, target in obs:
    if sym not in ("⊕", "⊗", "⊘", "⊛", "⊠"): continue
    env = {"a": a_val, "b": b_val, "n": 2, "i": 1, "d": 0}
    vals1 = {}
    for e in lvl1:
        try:
            v = eval(e, {}, env)
            if abs(v) <= 10000 and e not in vals1.values():
                vals1.setdefault(v, e)
        except Exception:
            pass
    hits = []
    for v1, e1 in vals1.items():
        if v1 == target:
            hits.append(e1)
        for v2, e2 in vals1.items():
            if v1 + v2 == target and v1 <= v2:
                hits.append(f"{e1}+{e2}")
            if v1 - v2 == target:
                hits.append(f"{e1}-{e2}")
            if v1 * v2 == target and 1 < abs(v1) <= abs(v2):
                hits.append(f"{e1}*{e2}")
    print(f"=== {sym} ({a_val}, {b_val}) -> {target} ===")
    for h in sorted(set(hits), key=len)[:35]:
        print(" ", h)
