# Exhaustive grammar search for each of the 9 operators matching all Phase 1 data!

# First, for single-operator unambiguous data points:
# Wait: some queries combined 2 or 3 operators, let us check consistency jointly too,
# starting from per-operator constraints implied if the other operator in the pair had its natural value,
# AND checking if ANY joint pair could deviate!

# Let us check ALL 5 multi-op queries for ANY alternative split!
# Q10: (6 ⊞ 16) ⊗ 100 = 2199.  (⊞ at 3,1,1; ⊗ at 3,2,0)
# Q11: 9 ⊛ (6 ⊕ 10) = 298.     (⊕ at 3,2,1; ⊛ at 3,1,0)
# Q12: 17 ⊘ (89 ⊠ 14) = -72.   (⊠ at 3,2,1; ⊘ at 3,1,0)
# Q13: (11 ◇ 34) ▽ 103 = 69.   (◇ at 3,1,1; ▽ at 3,2,0)
# Q14: 500 ⊠ ((12 △ 49) ⊗ 100) = 503. (⊠ at 4,1,0; △ at 4,2,2; ⊗ at 4,3,1)

atoms = ["a", "b", "n", "i", "d", "0", "1", "2"]
exprs = set(atoms)
# size 2-3 expressions
lvl1 = list(atoms)
for x in atoms:
    for y in atoms:
        if x in "012" and y in "012": continue
        for op in ["+", "-", "*", "//", "%"]:
            exprs.add(f"({x} {op} {y})")
        if y in ("2", "3", "n", "i", "d"):
            exprs.add(f"({x} ** {y})")
        exprs.add(f"max({x}, {y})")
        exprs.add(f"min({x}, {y})")
        exprs.add(f"abs({x} - {y})")

lvl2 = list(exprs)
for x in lvl2:
    for y in atoms:
        for op in ["+", "-", "*"]:
            exprs.add(f"({x} {op} {y})")
            if op == "-":
                exprs.add(f"({y} - {x})")
        exprs.add(f"max({x}, {y})")
        exprs.add(f"min({x}, {y})")

print("Total candidate ASTs generated:", len(exprs))

def find_matching(pts):
    good = []
    for e in exprs:
        ok = True
        for (a, b, n, i, d, target) in pts:
            try:
                v = eval(e, {"__builtins__": {"abs": abs, "max": max, "min": min}}, {"a": a, "b": b, "n": n, "i": i, "d": d})
                if v != target or isinstance(v, bool):
                    ok = False
                    break
            except Exception:
                ok = False
                break
        if ok:
            good.append(e)
    # deduplicate semantically over a grid of (a,b,n,i,d)
    grid = [
        (4, 7, 4, 1, 0), (4, 7, 4, 2, 1), (4, 7, 4, 3, 2),
        (9, 3, 4, 1, 1), (9, 3, 4, 2, 0), (9, 3, 4, 3, 1),
        (8, 8, 4, 2, 2), (-5, 7, 4, 1, 0)
    ]
    by_sig = {}
    for e in sorted(good, key=len):
        try:
            sig = tuple(eval(e, {"__builtins__": {"abs": abs, "max": max, "min": min}}, {"a": a, "b": b, "n": n, "i": i, "d": d}) for a,b,n,i,d in grid)
            by_sig.setdefault(sig, e)
        except Exception:
            pass
    return list(by_sig.values())

datasets = {
    "⊕": [(19, 5, 2, 1, 0, 25), (6, 10, 3, 2, 1, 17)],
    "⊗": [(19, 5, 2, 1, 0, 94), (22, 100, 3, 2, 0, 2199), (0, 100, 4, 3, 1, -1)],
    "◇": [(19, 5, 2, 1, 0, 19), (11, 34, 3, 1, 1, 34)],
    "▽": [(26, 3, 2, 1, 0, 23), (34, 103, 3, 2, 0, 69)],
    "⊘": [(26, 3, 2, 1, 0, 49), (17, 106, 3, 1, 0, -72)],
    "⊛": [(26, 3, 2, 1, 0, 35), (9, 17, 3, 1, 0, 298)],
    "⊞": [(26, 3, 2, 1, 0, 29), (6, 16, 3, 1, 1, 22)],
    "⊠": [(26, 3, 2, 1, 0, 31), (89, 14, 3, 2, 1, 106), (500, -1, 4, 1, 0, 503)],
    "△": [(26, 3, 2, 1, 0, 23), (12, 49, 4, 2, 2, 0)],
}

for sym, pts in datasets.items():
    m = find_matching(pts)
    print(f"=== {sym} ({len(m)} distinct semantics) ===")
    for e in m[:15]:
        print("  ", e)
'
